package de.kai.arbeitszeitgeofence
import android.Manifest
import android.os.Bundle
import androidx.activity.*
import androidx.activity.compose.setContent
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import de.kai.arbeitszeitgeofence.data.SettingsEntity
import de.kai.arbeitszeitgeofence.domain.*
import kotlinx.coroutines.launch
import java.time.*
class MainActivity: ComponentActivity(){ private val permissionLauncher=registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){ }; override fun onCreate(savedInstanceState: Bundle?){ super.onCreate(savedInstanceState); permissionLauncher.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.POST_NOTIFICATIONS)); val app=application as ArbeitszeitApp; val dao=app.database.workTimeDao(); setContent{ MaterialTheme{ val scope=rememberCoroutineScope(); val entries by dao.observeEntries().collectAsState(initial=emptyList()); val activeState by dao.observeActiveState().collectAsState(initial=null); val settings by dao.observeSettings().collectAsState(initial=null); var message by remember{ mutableStateOf("Bereit") }; LaunchedEffect(Unit){ if(dao.getActiveState()==null) dao.upsertActiveState(WorkSessionManager.initialState()); if(dao.getSettings()==null) dao.upsertSettings(SettingsEntity()) }; val state=activeState ?: WorkSessionManager.initialState(); val st=settings ?: SettingsEntity(); Column(Modifier.fillMaxSize().padding(16.dp), verticalArrangement=Arrangement.spacedBy(12.dp)){ Text("Arbeitszeit Geofence", style=MaterialTheme.typography.headlineMedium); Text("Status: ${if(state.isTracking) "Arbeitszeit läuft" else "Gestoppt"} / Geofence: ${if(state.insideGeofence) "Innen" else "Außen"}"); Text("Pause: ${state.accumulatedBreakMinutes} min${if(state.isBreakRunning) " + laufend" else ""}"); Text(message); Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){ Button(onClick={ scope.launch{ val current=dao.getActiveState() ?: WorkSessionManager.initialState(); dao.upsertActiveState(WorkSessionManager.startWork(current,Instant.now(),current.insideGeofence)); message="Manuell gestartet" } }){ Text("Start") }; Button(onClick={ scope.launch{ val current=dao.getActiveState() ?: WorkSessionManager.initialState(); val (newState,entry)=WorkSessionManager.stopWork(current,Instant.now(),LocalDate.now(),TrackingSource.Manual,"Manuell gestoppt"); if(entry!=null) dao.insertEntry(entry); dao.upsertActiveState(newState); message="Manuell gestoppt" } }){ Text("Stop") } }; Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){ Button(onClick={ scope.launch{ val current=dao.getActiveState() ?: WorkSessionManager.initialState(); dao.upsertActiveState(WorkSessionManager.startBreak(current,Instant.now())); message="Pause gestartet" } }){ Text("Pause Start") }; Button(onClick={ scope.launch{ val current=dao.getActiveState() ?: WorkSessionManager.initialState(); dao.upsertActiveState(WorkSessionManager.stopBreak(current,Instant.now())); message="Pause gestoppt" } }){ Text("Pause Stop") } }; Text("Einträge", style=MaterialTheme.typography.titleLarge); LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){ items(entries){ e -> val calc=TimeCalculator.calculate(Instant.ofEpochMilli(e.startEpochMillis),Instant.ofEpochMilli(e.endEpochMillis),e.breakMinutes,st.targetMinutesPerDay); Card(Modifier.fillMaxWidth()){ Column(Modifier.padding(12.dp)){ Text("${e.localDate} | ${e.source}"); Text("Netto: ${calc.netMinutes} min | Saldo: ${calc.balanceMinutes} min | Pause: ${e.breakMinutes} min"); if(e.comment.isNotBlank()) Text(e.comment) } } } } } } } } } }
